fn flip(a: &mut Vec<i32>, num: usize) {
    // Assumptions from the problem:
    // - a is non-empty
    // - num < a.len()
    debug_assert!(!a.is_empty());
    debug_assert!(num < a.len());

    let mut i: usize = 0;
    let mut j: usize = num;

    while i < j {
        a.swap(i, j);
        i += 1;
        j -= 1;
    }
}